  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Alprazolam, a 1,4-benzodiazepine sharing the 5-phenyl-7-chloro core, has an absolute oral bioavailability of 0.92 in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Estazolam, a structurally related benzodiazepine, showed 87% oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Clobazam, another benzodiazepine, has 90–100% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Adinazolam, a benzodiazepine with first-pass liability, still has approximately 40% absolute oral bioavailability, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Zotepine, a tricyclic antipsychotic, has only 7–13% bioavailability, but its low structural transferability to the benzodiazepine query limits its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is chlordiazepoxide, a 1,4-benzodiazepine N-oxide. Multiple structurally related benzodiazepines (alprazolam, estazolam, clobazam) show high oral bioavailability (87–100%), and even those with first-pass metabolism (adinazolam, triazolam) exceed 20%. The only low-bioavailability analogues are structurally distant tricyclic antipsychotics. Therefore, F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct experimental record for chlordiazepoxide itself; the closest analogues are triazolobenzodiazepines rather than N-oxide benzodiazepines.",
    "First-pass metabolism could reduce F, but all benzodiazepine analogues remain above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

